{
  "name": "@jfrz38/opencode-copy-last",
  "version": "0.2.0",
  "description": "Copy recent agent, user, or user-agent messages from the current OpenCode session.",
  "repository": {
    "type": "git",
    "url": "https://github.com/jfrz38/opencode-copy-last.git"
  },
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "default": "./dist/tui.js"
    },
    "./rpc": {
      "types": "./dist/rpc.d.ts",
      "default": "./dist/rpc.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "sideEffects": false,
  "keywords": [
    "opencode",
    "opencode-plugin",
    "clipboard",
    "copy-last",
    "ai"
  ],
  "author": "José F. Ruiz Zamora <jrz899@inlumine.ual.es>",
  "license": "MIT",
  "homepage": "https://github.com/jfrz38/opencode-copy-last#readme",
  "bugs": {
    "url": "https://github.com/jfrz38/opencode-copy-last/issues"
  },
  "engines": {
    "node": ">=20"
  },
  "dependencies": {
    "clipboardy": "5.3.2"
  },
  "devDependencies": {
    "@jfrz38/clean-architecture-highlighter-cli": "0.1.0",
    "@opencode-ai/plugin": "1.18.32",
    "@opencode/plugin": "2.0.29",
    "@types/node": "26.6.2",
    "eslint": "10.11.0",
    "husky": "9.1.7",
    "lint-staged": "17.5.1",
    "typescript": "6.0.3",
    "typescript-eslint": "8.70.1",
    "vitest": "5.0.1"
  },
  "lint-staged": {
    "*.{ts,tsx,js,jsx,mjs,cjs}": "eslint --fix"
  },
  "publishConfig": {
    "access": "public"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.0.29 <3"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    }
  },
  "scripts": {
    "clean": "node -e \"fs.rmSync('dist', { recursive: true, force: true })\"",
    "build": "pnpm clean && tsc -p tsconfig.build.json",
    "lint": "eslint .",
    "test": "vitest run",
    "test:smoke": "node scripts/smoke-opencode-compatibility.mjs",
    "test:watch": "vitest",
    "typecheck": "tsc -p tsconfig.json",
    "arch:check": "clean-arch check ./src",
    "check": "pnpm lint && pnpm typecheck && pnpm test && pnpm build",
    "package": "pnpm pack",
    "pack:dry-run": "pnpm publish --dry-run",
    "publish:npm": "pnpm publish --access public"
  }
}
